#include "v42_link.h"
#include <string.h>
static unsigned cr(const struct v42_link*l,int response){return(unsigned)(response?!l->originator:l->originator);}
void v42_link_init(struct v42_link*l,int originator){memset(l,0,sizeof*l);l->originator=!!originator;l->t401_ms=1000;l->max_retries=3;if(l->originator){l->state=V42_LINK_AWAIT_UA;l->pending=V42_LAPM_SABME;l->have_pending=1;}}
size_t v42_link_next(struct v42_link*l,uint8_t*bits,size_t cap){if(!l->have_pending)return 0;enum v42_lapm_u u=l->pending;l->have_pending=0;int response=u==V42_LAPM_UA||u==V42_LAPM_DM;size_t n=v42_lapm_encode_u(u,cr(l,response),1,0,0,bits,cap);if(n&&(u==V42_LAPM_SABME||u==V42_LAPM_DISC))l->deadline_ms=l->now_ms+l->t401_ms;return n;}
int v42_link_receive(struct v42_link*l,const uint8_t*bits,size_t n){struct v42_lapm_frame f;if(v42_lapm_decode(bits,n,&f)<0||f.type!=V42_LAPM_U)return-1;if(f.u_control==V42_LAPM_SABME){l->state=V42_LINK_CONNECTED;l->deadline_ms=0;l->pending=V42_LAPM_UA;l->have_pending=1;return 1;}if(f.u_control==V42_LAPM_UA&&l->state==V42_LINK_AWAIT_UA){l->state=V42_LINK_CONNECTED;l->deadline_ms=0;l->retries=0;return 1;}if(f.u_control==V42_LAPM_UA&&l->state==V42_LINK_AWAIT_RELEASE){l->state=V42_LINK_DISCONNECTED;l->deadline_ms=0;return 0;}if(f.u_control==V42_LAPM_DISC){l->state=V42_LINK_DISCONNECTED;l->pending=V42_LAPM_UA;l->have_pending=1;return 0;}if(f.u_control==V42_LAPM_DM){l->state=V42_LINK_FAILED;l->deadline_ms=0;return-1;}return 0;}
void v42_link_advance(struct v42_link*l,unsigned ms){l->now_ms+=ms;if((l->state!=V42_LINK_AWAIT_UA&&l->state!=V42_LINK_AWAIT_RELEASE)||!l->deadline_ms||l->now_ms<l->deadline_ms)return;if(l->retries++>=l->max_retries){l->state=V42_LINK_FAILED;l->deadline_ms=0;return;}l->pending=l->state==V42_LINK_AWAIT_UA?V42_LAPM_SABME:V42_LAPM_DISC;l->have_pending=1;l->deadline_ms=0;}
void v42_link_disconnect(struct v42_link*l){if(l->state==V42_LINK_CONNECTED){l->state=V42_LINK_AWAIT_RELEASE;l->pending=V42_LAPM_DISC;l->have_pending=1;l->retries=0;}}
